//go:build phpx

package phpx

import "github.com/titpetric/phpx/runner"

func init() {
	runner.RegisterArea(`Runtime\PX\ConstantsInstall`, registerGeneratedConstants)
}

// registerGeneratedConstants defines the constants of the carried extensions
// that the runtime has not defined itself (constants_gen.go is generated by
// phpx/scripts/gen-consts.php, then gofmt).
func registerGeneratedConstants(rt *runner.Runtime) {
	define := func(name string, value any) {
		if _, taken := rt.Const(name); !taken {
			rt.SetConst(name, value)
		}
	}
	for name, v := range phpxGenIntConstants {
		define(name, v)
	}
	for name, v := range phpxGenFloatConstants {
		define(name, v)
	}
	for name, v := range phpxGenStringConstants {
		define(name, v)
	}
	for name, v := range phpxGenBoolConstants {
		define(name, v)
	}
}
